-- DM26-EX4 provisional release-stage import, NOT official card-catalog data.
-- Official evidence: https://dm.takaratomy.co.jp/product/dm26ex4/; card-name/number evidence: https://m.dmwiki.net/DM26-EX4 (unverified).
-- Run only from the dedicated Price_DM release session after conflict checks.
begin;
set local lock_timeout='5s';
lock table public.card_products, public.canonical_cards, public.card_prints, public.card_search_terms in share row exclusive mode;
select pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('dm26ex4-provisional', 0));
do $$ begin if (select md5(string_agg(version||':'||name,',' order by version)) from supabase_migrations.schema_migrations where version<>'20261009171721') is distinct from 'ce08ebeab09f20713f498f8f46a14617' then raise exception 'Release safety checksum changed: history'; end if;
if (select md5(string_agg((to_jsonb(c)-'metadata_provenance')::text,',' order by id)) from public.canonical_cards c where source_checked_at is not null) is distinct from '462e710a8336476919007fcdd84669fc' then raise exception 'Release safety checksum changed: formal_cards_hash'; end if;
if (select md5(string_agg((to_jsonb(p)-array['metadata_provenance','source_metadata'])::text,',' order by id)) from public.card_prints p where product_id is distinct from 266) is distinct from '27eebe87cdae79de27ba9abe24320444' then raise exception 'Release safety checksum changed: other_prints_hash'; end if;
if (select md5(string_agg(to_jsonb(p)::text,',' order by id)) from public.card_products p) is distinct from '100b0ad70f9717e4cb9e7c63612b6393' then raise exception 'Release safety checksum changed: products_hash'; end if;
if (select md5(string_agg(to_jsonb(t)::text,',' order by id)) from public.card_search_terms t where id<=103498) is distinct from 'df77f874f68728af1810968a40222f09' then raise exception 'Release safety checksum changed: terms_hash'; end if;
if (select md5(string_agg((to_jsonb(c)-array['metadata_provenance','updated_at','name_kana','cost','cost_is_infinite','civilizations','card_types','races','power_text','power_value'])::text,',' order by id)) from public.canonical_cards c where id<=43938) is distinct from 'f086ab2f24e837dd3ef78d1fae2ccf40' then raise exception 'Release safety checksum changed: canonical_identity_hash'; end if;
if (select count(*) from public.card_prints where product_id=266)<>48 then raise exception 'DM26-EX4 baseline changed'; end if;
end $$;
