do $$ begin
  if not exists(select 1 from public.canonical_cards where id=535 and name='ジョギラゴン＆ジョニー ～Jの旅路～' and game_id=(select id from public.tcg_games where slug='duel-masters') and deleted_at is null) or not exists(select 1 from public.card_prints where canonical_card_id=535 and official_card_id='dm26sd1-n001' and official_url='https://dm.takaratomy.co.jp/card/detail/?id=dm26sd1-n001' and deleted_at is null) then raise exception 'Audited canonical mapping changed; manual review required'; end if;
  if not exists(select 1 from public.canonical_cards where id=5196 and name='龍月 ドラグ・スザーク / 龍・獄・殺' and game_id=(select id from public.tcg_games where slug='duel-masters') and deleted_at is null) or not exists(select 1 from public.card_prints where canonical_card_id=5196 and official_card_id='dmbd22-014' and official_url='https://dm.takaratomy.co.jp/card/detail/?id=dmbd22-014' and deleted_at is null) then raise exception 'Audited canonical mapping changed; manual review required'; end if;
  if not exists(select 1 from public.canonical_cards where id=7504 and name='バーンメア・ザ・シルバー / オラオラ・スラッシュ' and game_id=(select id from public.tcg_games where slug='duel-masters') and deleted_at is null) or not exists(select 1 from public.card_prints where canonical_card_id=7504 and official_card_id='dmrp20-a12' and official_url='https://dm.takaratomy.co.jp/card/detail/?id=dmrp20-a12' and deleted_at is null) then raise exception 'Audited canonical mapping changed; manual review required'; end if;
  if not exists(select 1 from public.canonical_cards where id=10742 and name='音奏 ハイオリーダ / 音奏曲第3番「幻惑」' and game_id=(select id from public.tcg_games where slug='duel-masters') and deleted_at is null) or not exists(select 1 from public.card_prints where canonical_card_id=10742 and official_card_id='dmex05-021' and official_url='https://dm.takaratomy.co.jp/card/detail/?id=dmex05-021' and deleted_at is null) then raise exception 'Audited canonical mapping changed; manual review required'; end if;
  if not exists(select 1 from public.canonical_cards where id=7795 and name='スゴ腕プロジューサー / りんご娘はさんにんっ娘' and game_id=(select id from public.tcg_games where slug='duel-masters') and deleted_at is null) or not exists(select 1 from public.card_prints where canonical_card_id=7795 and official_card_id='dmex17-047' and official_url='https://dm.takaratomy.co.jp/card/detail/?id=dmex17-047' and deleted_at is null) then raise exception 'Audited canonical mapping changed; manual review required'; end if;
  if not exists(select 1 from public.canonical_cards where id=1120 and name='欲望の邪道 ニガ=アブシューム / 支配の邪道 獄鬼夜城' and game_id=(select id from public.tcg_games where slug='duel-masters') and deleted_at is null) or not exists(select 1 from public.card_prints where canonical_card_id=1120 and official_card_id='dm25ex2-045' and official_url='https://dm.takaratomy.co.jp/card/detail/?id=dm25ex2-045' and deleted_at is null) then raise exception 'Audited canonical mapping changed; manual review required'; end if;
  if not exists(select 1 from public.canonical_cards where id=1164 and name='炎龍覇 グレンアイラ / 「助けて！モルト!!」' and game_id=(select id from public.tcg_games where slug='duel-masters') and deleted_at is null) or not exists(select 1 from public.card_prints where canonical_card_id=1164 and official_card_id='dm25bd3-016' and official_url='https://dm.takaratomy.co.jp/card/detail/?id=dm25bd3-016' and deleted_at is null) then raise exception 'Audited canonical mapping changed; manual review required'; end if;
  if not exists(select 1 from public.tcg_games where slug='duel-masters') then
    raise exception 'Duel Masters game not found';
  end if;
  if exists(select 1 from public.card_products where product_code='DM26-EX4' and (official_url is distinct from 'https://dm.takaratomy.co.jp/product/dm26ex4/'
    or product_name is distinct from 'DM26-EX4 デュエル・マスターズTCG 切札不滅!! デュエキング FOREVER 2026' or release_date is distinct from '2026-10-17'::date
    or release_date_precision <> 'day' or game_id <> (select id from public.tcg_games where slug='duel-masters'))) then
    raise exception 'DM26-EX4 product already has a different source URL; manual review required';
  end if;
  if exists(select 1 from public.card_prints p join dm26ex4_preview s on p.card_number=s.card_number
    left join public.card_products product on product.id=p.product_id
    where product.product_code is distinct from 'DM26-EX4') then
    raise exception 'Unlinked or differently linked DM26-EX4 print; manual review required';
  end if;
  if exists(select 1 from dm26ex4_preview s join public.canonical_cards c
    on c.game_id=(select id from public.tcg_games where slug='duel-masters')
    and public.normalize_card_search(c.name)=public.normalize_card_search(s.name)
    where c.deleted_at is not null or c.normalized_name_nfkc<>pg_catalog.normalize(s.name,'NFKC')) then
    raise exception 'Ambiguous canonical name; manual review required';
  end if;
  if exists(select 1 from public.card_prints p join public.card_products product on product.id=p.product_id
    join dm26ex4_preview s on s.card_number=p.card_number where product.product_code='DM26-EX4'
    group by p.card_number having count(*)>1) then raise exception 'Duplicate existing print; manual review required'; end if;
  if exists(
    select 1 from dm26ex4_preview s
    join public.card_products product on product.product_code='DM26-EX4'
    join public.card_prints print on print.product_id=product.id and print.card_number=s.card_number
    left join public.canonical_cards card on card.id=print.canonical_card_id
    where print.deleted_at is not null or card.id is null or card.deleted_at is not null
       or pg_catalog.normalize(card.name,'NFKC') <> pg_catalog.normalize(s.name,'NFKC')
  ) then raise exception 'Conflicting or deleted DM26-EX4 print; manual review required'; end if;
end $$;

insert into public.card_products(game_id,product_code,product_name,release_date,release_date_precision,official_url,source_checked_at)
select g.id, 'DM26-EX4', 'DM26-EX4 デュエル・マスターズTCG 切札不滅!! デュエキング FOREVER 2026', '2026-10-17'::date, 'day', 'https://dm.takaratomy.co.jp/product/dm26ex4/', now()
from public.tcg_games g where g.slug='duel-masters'
on conflict(game_id,product_code) do nothing;

-- Only create new canonical names; NEVER treat wiki names as official assertions or overwrite official fields.
insert into public.canonical_cards(game_id,name,source_name,source_name_kana,name_kana,cost,civilizations,card_types,source_checked_at)
select distinct on (pg_catalog.normalize(s.name,'NFKC')) g.id,s.name,s.name,null,null,null,'{}'::text[],'{}'::text[],null
from dm26ex4_preview s cross join public.tcg_games g where g.slug='duel-masters'
order by pg_catalog.normalize(s.name,'NFKC'),s.name collate "C"
on conflict(game_id,normalized_name_nfkc) where deleted_at is null do nothing;

-- Provisional prints have null official_card_id and null official_url by design.
insert into public.card_prints(canonical_card_id,official_card_id,card_number,product_name,official_url,source_checked_at,product_id)
select c.id,null,s.card_number,'DM26-EX4 デュエル・マスターズTCG 切札不滅!! デュエキング FOREVER 2026',null,null,p.id
from dm26ex4_preview s
cross join public.tcg_games g
join public.card_products p on p.game_id=g.id and p.product_code='DM26-EX4'
join public.canonical_cards c on c.game_id=g.id and c.normalized_name_nfkc=pg_catalog.normalize(s.name,'NFKC') and c.deleted_at is null
where g.slug='duel-masters' and not exists(
  select 1 from public.card_prints old where old.product_id=p.id and old.card_number=s.card_number
)
on conflict do nothing;

-- Unverified card title search entry: never update existing official terms.
insert into public.card_search_terms(canonical_card_id,term,normalized_term,term_kind,source,verified,priority)
select distinct on (c.id,public.normalize_card_search(s.name)) c.id,s.name,
  public.normalize_card_search(s.name),'alias','dmwiki',false,40
from dm26ex4_preview s cross join public.tcg_games g
join public.canonical_cards c on c.game_id=g.id and c.normalized_name_nfkc=pg_catalog.normalize(s.name,'NFKC') and c.deleted_at is null
where g.slug='duel-masters' and public.normalize_card_search(s.name)<>''
order by c.id,public.normalize_card_search(s.name),s.name collate "C"
on conflict(canonical_card_id,normalized_term,term_kind) do nothing;

select count(*) as staged_previews from dm26ex4_preview;

create temporary table dm26ex4_detail(number text primary key,record jsonb) on commit drop;
