update public.canonical_cards c set name_kana=case when c.name_kana is null then 'おうどうせいれい アルファディオス' else c.name_kana end,cost=case when c.cost is null then 7 else c.cost end,civilizations=case when cardinality(c.civilizations)=0 then array['light','water','nature']::text[] else c.civilizations end,card_types=case when cardinality(c.card_types)=0 then array['NEOドリーム・クリーチャー']::text[] else c.card_types end,races=case when cardinality(c.races)=0 then array['エンジェル・コマンド']::text[] else c.races end,power_text=case when c.power_text is null then '12500' else c.power_text end,power_value=case when c.power_value is null then 12500 else c.power_value end,metadata_provenance=c.metadata_provenance||case when c.name_kana is null then jsonb_build_object('name_kana','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E7%8E%8B%E5%B0%8E%E8%81%96%E9%9C%8A%20%E3%82%A2%E3%83%AB%E3%83%95%E3%82%A1%E3%83%87%E3%82%A3%E3%82%AA%E3%82%B9%E3%80%8B","status":"observed","value":"おうどうせいれい アルファディオス"}'::jsonb) else '{}'::jsonb end||case when c.cost is null then jsonb_build_object('cost','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E7%8E%8B%E5%B0%8E%E8%81%96%E9%9C%8A%20%E3%82%A2%E3%83%AB%E3%83%95%E3%82%A1%E3%83%87%E3%82%A3%E3%82%AA%E3%82%B9%E3%80%8B","status":"observed","value":7}'::jsonb) else '{}'::jsonb end||case when cardinality(c.civilizations)=0 then jsonb_build_object('civilizations','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E7%8E%8B%E5%B0%8E%E8%81%96%E9%9C%8A%20%E3%82%A2%E3%83%AB%E3%83%95%E3%82%A1%E3%83%87%E3%82%A3%E3%82%AA%E3%82%B9%E3%80%8B","status":"observed","value":["light","water","nature"]}'::jsonb) else '{}'::jsonb end||case when cardinality(c.card_types)=0 then jsonb_build_object('card_types','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E7%8E%8B%E5%B0%8E%E8%81%96%E9%9C%8A%20%E3%82%A2%E3%83%AB%E3%83%95%E3%82%A1%E3%83%87%E3%82%A3%E3%82%AA%E3%82%B9%E3%80%8B","status":"observed","value":["NEOドリーム・クリーチャー"]}'::jsonb) else '{}'::jsonb end||case when cardinality(c.races)=0 then jsonb_build_object('races','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E7%8E%8B%E5%B0%8E%E8%81%96%E9%9C%8A%20%E3%82%A2%E3%83%AB%E3%83%95%E3%82%A1%E3%83%87%E3%82%A3%E3%82%AA%E3%82%B9%E3%80%8B","status":"observed","value":["エンジェル・コマンド"]}'::jsonb) else '{}'::jsonb end||case when c.power_text is null then jsonb_build_object('power_text','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E7%8E%8B%E5%B0%8E%E8%81%96%E9%9C%8A%20%E3%82%A2%E3%83%AB%E3%83%95%E3%82%A1%E3%83%87%E3%82%A3%E3%82%AA%E3%82%B9%E3%80%8B","status":"observed","value":"12500"}'::jsonb) else '{}'::jsonb end||case when c.power_value is null then jsonb_build_object('power_value','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E7%8E%8B%E5%B0%8E%E8%81%96%E9%9C%8A%20%E3%82%A2%E3%83%AB%E3%83%95%E3%82%A1%E3%83%87%E3%82%A3%E3%82%AA%E3%82%B9%E3%80%8B","status":"observed","value":12500}'::jsonb) else '{}'::jsonb end,updated_at=now()
where c.normalized_name_nfkc=pg_catalog.normalize('王導聖霊 アルファディオス','NFKC') and c.game_id=(select id from public.tcg_games where slug='duel-masters')
and c.deleted_at is null and not c.manually_locked and c.source_checked_at is null
and ((c.name_kana is null) or (c.cost is null) or (cardinality(c.civilizations)=0) or (cardinality(c.card_types)=0) or (cardinality(c.races)=0) or (c.power_text is null) or (c.power_value is null))
and not exists(select 1 from public.card_prints p where p.canonical_card_id=c.id and p.deleted_at is null and p.official_card_id is not null);
