case when cardinality(c.races)=0 then jsonb_build_object('races','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E5%88%87%E6%9C%AD%E7%B8%AB%E5%90%88%20%E3%82%A2%E3%83%93%E3%82%B9%E8%A8%98%E5%8F%B7jS%E3%80%8B","status":"observed","value":["ディスペクター","クリスタル・コマンド・ドラゴン","アビスロイヤル"]}'::jsonb) else '{}'::jsonb end||case when c.power_text is null then jsonb_build_object('power_text','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E5%88%87%E6%9C%AD%E7%B8%AB%E5%90%88%20%E3%82%A2%E3%83%93%E3%82%B9%E8%A8%98%E5%8F%B7jS%E3%80%8B","status":"observed","value":"6000"}'::jsonb) else '{}'::jsonb end||case when c.power_value is null then jsonb_build_object('power_value','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E5%88%87%E6%9C%AD%E7%B8%AB%E5%90%88%20%E3%82%A2%E3%83%93%E3%82%B9%E8%A8%98%E5%8F%B7jS%E3%80%8B","status":"observed","value":6000}'::jsonb) else '{}'::jsonb end,updated_at=now()
where c.normalized_name_nfkc=pg_catalog.normalize('切札縫合 アビス記号jS','NFKC') and c.game_id=(select id from public.tcg_games where slug='duel-masters')
and c.deleted_at is null and not c.manually_locked and c.source_checked_at is null
and ((c.name_kana is null) or (c.cost is null) or (cardinality(c.civilizations)=0) or (cardinality(c.card_types)=0) or (cardinality(c.races)=0) or (c.power_text is null) or (c.power_value is null))
and not exists(select 1 from public.card_prints p where p.canonical_card_id=c.id and p.deleted_at is null and p.official_card_id is not null);
update public.card_prints p set source_metadata=p.source_metadata||jsonb_build_object('dmwiki',s.record->'detail'),updated_at=now()
from dm26ex4_detail s join public.card_products product on product.product_code='DM26-EX4'
where p.product_id=product.id and p.card_number=s.number and p.deleted_at is null and not p.manually_locked
and s.record->'detail'<>'null'::jsonb and not p.source_metadata ? 'dmwiki';
update public.card_prints p set card_texts=array['自分のマナゾーンにエンジェル・コマンド・カードが3枚以上あれば、このクリーチャーを[光/水/自然(5)]支払って召喚してもよい。
NEO進化：光、水、または自然のクリーチャー1体の上に置いてもよい。
超魂レイド
T・ブレイカー
相手は光ではない呪文を唱えられない。
このクリーチャーが攻撃する時、このクリーチャーに含まれるカード1枚につき、カードを1枚引いてもよい。その後、エンジェル・コマンドを1つ、自分の手札から出してもよい。']::text[],metadata_provenance=p.metadata_provenance||jsonb_build_object('card_texts','{"source":"dmwiki","verified":false,"source_url":"https://m.dmwiki.net/%E3%80%8A%E7%8E%8B%E5%B0%8E%E8%81%96%E9%9C%8A%20%E3%82%A2%E3%83%AB%E3%83%95%E3%82%A1%E3%83%87%E3%82%A3%E3%82%AA%E3%82%B9%E3%80%8B","status":"observed","value":["自分のマナゾーンにエンジェル・コマンド・カードが3枚以上あれば、このクリーチャーを[光/水/自然(5)]支払って召喚してもよい。\nNEO進化：光、水、または自然のクリーチャー1体の上に置いてもよい。\n超魂レイド\nT・ブレイカー\n相手は光ではない呪文を唱えられない。\nこのクリーチャーが攻撃する時、このクリーチャーに含まれるカード1枚につき、カードを1枚引いてもよい。その後、エンジェル・コマンドを1つ、自分の手札から出してもよい。"]}'::jsonb),updated_at=now()
