where p.card_number='DM26EX4 ㊙22/㊙25' and p.product_id=(select id from public.card_products where product_code='DM26-EX4') and p.deleted_at is null and not p.manually_locked
and p.official_card_id is null and p.source_checked_at is null and cardinality(p.card_texts)=0;
insert into public.card_search_terms(canonical_card_id,term,normalized_term,term_kind,source,verified,priority)
select c.id,'きりふだほうごう アビスきごうジャシンサイクル',public.normalize_card_search('きりふだほうごう アビスきごうジャシンサイクル'),'alias_reading','dmwiki',false,40 from public.canonical_cards c
